edits.original:
.welcome-hero {
  min-height: calc(100vh - 96px);
  background:
    radial-gradient(
      1200px 500px at 85% -10%,
      rgba(245, 158, 11, 0.22),
      transparent 60%
    ),
    radial-gradient(
      900px 420px at 10% 110%,
      rgba(2, 132, 199, 0.25),
      transparent 60%
    ),
    linear-gradient(160deg, #0f172a 0%, #1e293b 55%, #0b1120 100%);
  color: #fff;
  padding: 40px 28px 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.welcome-clock {
  font-size: 58px;
  font-weight: 900;
  letter-spacing: 2px;
  font-variant-numeric: tabular-nums;
  color: #fbbf24;
  text-shadow: 0 0 30px rgba(251, 191, 36, 0.35);
  line-height: 1.1;
}

.welcome-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  width: 100%;
  max-width: 880px;
  margin-top: 8px;
}

.welcome-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 18px 20px;
  text-align: left;
}

.hist-card {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 12px 16px;
  cursor: pointer;
  transition: all 0.15s;
}

.hist-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.hist-compare {
  display: none;
  margin-top: 10px;
  border-top: 1px dashed #cbd5e1;
  padding-top: 10px;
}

.hist-compare-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  table-layout: fixed;
}

.hist-compare-table th,
.hist-compare-table td {
  padding: 5px 8px;
  border-bottom: 1px solid #f1f5f9;
  text-align: left;
}

.hist-actions {
  margin-top: 8px;
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.item-draw-overlay {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 12500;
  background: rgba(2, 6, 23, 0.78);
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.item-draw-board {
  width: min(1100px, 96vw);
  max-height: 90vh;
  overflow: auto;
  background: rgba(240, 249, 255, 0.96);
  border-radius: 20px;
  padding: 22px;
  box-shadow: 0 24px 80px #0008;
}

.item-draw-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.item-draw-card {
  background: #fff;
  border: 1px solid #bfdbfe;
  border-radius: 14px;
  padding: 15px;
  text-align: center;
}
